import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"巽","description":"焦氏易林注 - 巽","frontmatter":{"title":"巽","description":"焦氏易林注 - 巽"},"headers":[],"relativePath":"zh/classics/jiaoyilin/057.md","filePath":"zh/classics/jiaoyilin/057.md"}'),l={name:"zh/classics/jiaoyilin/057.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="巽" tabindex="-1">巽 <a class="header-anchor" href="#巽" aria-label="Permalink to “巽”">​</a></h1><h3 id="巽-1" tabindex="-1">巽 <a class="header-anchor" href="#巽-1" aria-label="Permalink to “巽”">​</a></h3><h3 id="巽之乾" tabindex="-1">巽之乾 <a class="header-anchor" href="#巽之乾" aria-label="Permalink to “巽之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>採唐沬鄉，要期桑中。失信不會，憂思約帶。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《噬嗑》。○期，汲古作我，思約作在鉤，均依宋元本。</p><h3 id="巽之坤" tabindex="-1">巽之坤 <a class="header-anchor" href="#巽之坤" aria-label="Permalink to “巽之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>有鳥飛來，集於宮樹。鳴聲可惡，主將出去。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《夬》。○可惡，汲古作畏惡，依宋元本。</p><h3 id="巽之屯" tabindex="-1">巽之屯 <a class="header-anchor" href="#巽之屯" aria-label="Permalink to “巽之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>仁政之德，參參日息。成都就邑，日受厥福。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《旅》之《臨》。○參參，局本作恭恭。</p><h3 id="巽之蒙" tabindex="-1">巽之蒙 <a class="header-anchor" href="#巽之蒙" aria-label="Permalink to “巽之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>他山之錯，與璆為仇。來攻吾城，傷我肌膚，邦家搔憂。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》。○錯，宋元本作儲，來，汲古作夾，依宋元本。</p><h3 id="巽之需" tabindex="-1">巽之需 <a class="header-anchor" href="#巽之需" aria-label="Permalink to “巽之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>貝贖狸，不聽我辭。繫於虎鬚，牽不得來。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《革》。</p><h3 id="巽之訟" tabindex="-1">巽之訟 <a class="header-anchor" href="#巽之訟" aria-label="Permalink to “巽之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>一簧兩舌，佞言諂語。三姦成虎，曾母投杼。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《乾》。○佞，宋元本作妄，依汲古。</p><h3 id="巽之師" tabindex="-1">巽之師 <a class="header-anchor" href="#巽之師" aria-label="Permalink to “巽之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>魁行搖尾，逐雲吹水。污泥為陸，下田宜稷。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《漸》。首句宋元本汲古皆作薄行搔尾，依《同人》之《漸》校。</p><h3 id="巽之比" tabindex="-1">巽之比 <a class="header-anchor" href="#巽之比" aria-label="Permalink to “巽之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>天門九重，深內難通。明登至莫，不見神公。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮居戌亥，故曰天門。內經以戌亥為天門，辰巳為地戶是也。坤為重，數九，故曰天門九重。《漢上易》謂坤納癸，自乙至癸，故數九也。重坤，故曰深，坤閉，故曰難通。艮為光明，坎為莫，震為神、為公，三五震覆，又坎為隱，故不見也。《後漢郎顗傳》神在天門，出入聽候，言神在戌亥，司候帝王興衰得失。○深，汲古作澤。登，宋元本作坐，依汲古。至，汲古作到，依宋元本。</p><h3 id="巽之小畜" tabindex="-1">巽之小畜 <a class="header-anchor" href="#巽之小畜" aria-label="Permalink to “巽之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>暗目失明，耳閼不聰。陷入深淵，滅頂憂凶。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>二至四兌，易以兌為眇，故曰暗目失明。又離為目，伏坎，故曰暗目也。伏坎為耳、為塞，故曰耳閼不聰。閼，音遏，壅塞也。伏坤為淵，坎陷。艮為頂，坤為滅、為凶，故曰滅頂憂凶。坎水，坤水，故有此象。○目失，汲古作昧不，閼作聾，憂作成，均依宋元本。不聰，宋元本作聽聰，非，依汲古。頂，元本訛頃。</p><h3 id="巽之履" tabindex="-1">巽之履 <a class="header-anchor" href="#巽之履" aria-label="Permalink to “巽之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>霧露早霜，日暗不明。陰陽孽疾，年谷大傷。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>伏坎為霧露，坤為霜，離為日，伏坎，故不明。但林詞似全用旁通，艮亦為日，與坎連體，故曰不明也。坎為疾，震為谷，坤為年歲、為喪，故曰年谷大傷。</p><h3 id="巽之泰" tabindex="-1">巽之泰 <a class="header-anchor" href="#巽之泰" aria-label="Permalink to “巽之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>三階土廊，德義明堂。交讓往來，享燕相承。箕伯朝王，錫我玄黃。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>《漢書東方朔傳》註：泰階者，天之三階也。上階為天子，中階為諸侯公卿大夫，下階為士庶人。坤為階，震數三，故曰三階。艮為廊、為明堂，兌為燕享。震為伯、為箕，乾為王，天玄地黃，故曰錫我玄黃。○階，宋元本訛諧，依汲古。</p><h3 id="巽之否" tabindex="-1">巽之否 <a class="header-anchor" href="#巽之否" aria-label="Permalink to “巽之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>爭雞失羊，利得不長。陳蔡之患，賴楚以安。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>巽為雞，兌為羊，兌伏，故失羊。巽為利、為長，坤喪，故曰不長。震為陳、為蔡、為楚，坤為患，艮為安。《史記》孔子厄於陳蔡，楚昭王發兵救之，得免。</p><h3 id="巽之同人" tabindex="-1">巽之同人 <a class="header-anchor" href="#巽之同人" aria-label="Permalink to “巽之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>天旱水涸，枯槁無澤，未有所獲。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>火在天下，故曰天旱。坎伏，故曰水涸。離為枯槁。</p><h3 id="巽之大有" tabindex="-1">巽之大有 <a class="header-anchor" href="#巽之大有" aria-label="Permalink to “巽之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>陶朱白圭，善賈息貲。公子王孫，富利不貧。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>乾為大赤，離火，故曰陶朱。乾為玉，乾金色白，故曰白圭。遇卦巽為商賈、為利，故曰善賈息貲。伏震為公、為子、為王，艮孫，故曰公子王孫。重巽，故曰富利不貧。○貲，宋元本作資，依汲古。</p><h3 id="巽之謙" tabindex="-1">巽之謙 <a class="header-anchor" href="#巽之謙" aria-label="Permalink to “巽之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>龜厭江海，陸行不止。自令枯槁，失其都市，憂悔無咎。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《節》。</p><h3 id="巽之豫" tabindex="-1">巽之豫 <a class="header-anchor" href="#巽之豫" aria-label="Permalink to “巽之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>黃鳥採蓄，既嫁不答。念吾父兄，思復邦國。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>《詩小雅黃鳥篇》言旋言歸，復我諸兄，復我諸父；《我行篇》言採其蓫，爾不我畜，復我邦族，皆刺禮教不行、婦中道見棄之詩。蓫，《釋文》雲本又作蓄，今易林即作蓄，是焦與毛詩異讀也。震為黃，艮為鳥、為採，震為蓄。蓄，冬菜也。震為嫁，二至四震反，故雲不答。坎為思念，伏乾為父，震為兄，坤為吾、為邦國，震反，故曰復。</p><h3 id="巽之隨" tabindex="-1">巽之隨 <a class="header-anchor" href="#巽之隨" aria-label="Permalink to “巽之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>田鼠野雞，意常欲逃。拘制籠檻，不得動搖。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《隨》。</p><h3 id="巽之蠱" tabindex="-1">巽之蠱 <a class="header-anchor" href="#巽之蠱" aria-label="Permalink to “巽之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>平國不君，夏氏作亂。烏號竊發，靈公殞命。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《晉》。</p><h3 id="巽之臨" tabindex="-1">巽之臨 <a class="header-anchor" href="#巽之臨" aria-label="Permalink to “巽之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>巨蛇大暎戰於國郊。上下閉塞，君主走逃。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《艮》。</p><h3 id="巽之觀" tabindex="-1">巽之觀 <a class="header-anchor" href="#巽之觀" aria-label="Permalink to “巽之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>讒言亂國，覆是為非。伯奇流離，共子憂哀。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《豐》之《鼎》。</p><h3 id="巽之噬嗑" tabindex="-1">巽之噬嗑 <a class="header-anchor" href="#巽之噬嗑" aria-label="Permalink to “巽之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>鬱不明，為陰所傷。眾霧集聚，共奪日光。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《艮》。○，宋元本訛映，依汲古。</p><h3 id="巽之賁" tabindex="-1">巽之賁 <a class="header-anchor" href="#巽之賁" aria-label="Permalink to “巽之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>望城抱子，見邑不殆。公孫上堂，大君歡喜。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>離為望，艮為城、為抱，震子，故曰望城抱子。艮為邑，坎為殆，震解，故不殆。艮為孫、為堂，震為公，故曰公孫上堂。震為君、為喜。殆，音以。</p><h3 id="巽之剝" tabindex="-1">巽之剝 <a class="header-anchor" href="#巽之剝" aria-label="Permalink to “巽之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>三蟲為蠱，剗跡無與。勝母盜泉，君子弗處。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《困》。○蟲，從宋元，汲古作蟲。為，宋元本作作，茲依汲古。</p><h3 id="巽之復" tabindex="-1">巽之復 <a class="header-anchor" href="#巽之復" aria-label="Permalink to “巽之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>車馳人趨，捲甲相求。齊魯寇戰，敗於犬丘。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《兌》。戰，宋元本作戎，依汲古。</p><h3 id="巽之無妄" tabindex="-1">巽之無妄 <a class="header-anchor" href="#巽之無妄" aria-label="Permalink to “巽之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>欲訪子車，善相欺紿。桓叔相迎，不見所期。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>初至四正反震，故曰欺紿。艮為叔、為木，故曰桓叔。《說文》桓，郵亭表也。其事未詳。</p><h3 id="巽之大畜" tabindex="-1">巽之大畜 <a class="header-anchor" href="#巽之大畜" aria-label="Permalink to “巽之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>爭雞失羊，亡其金囊，利得不長。陳蔡之患，賴楚以安。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>詳《恆》之《夬》。</p><h3 id="巽之頤" tabindex="-1">巽之頤 <a class="header-anchor" href="#巽之頤" aria-label="Permalink to “巽之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>歲暮花落，陽入陰室。萬物伏匿，利不可得。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤候卦為亥，故曰歲暮。兌為華，兌伏不見，故曰花落。乾本居亥，坤行至亥陰牝陽，故曰陽入陰室。艮為室，即文言所謂陰凝於陽也。坤為萬物所藏，故曰伏匿。巽為利，巽伏，故曰利不可得。○匿利，宋元本作藏匿，依汲古。</p><h3 id="巽之大過" tabindex="-1">巽之大過 <a class="header-anchor" href="#巽之大過" aria-label="Permalink to “巽之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>晨風文翰，大舉就溫。昧過我邑，羿無所得。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《革》。翰，宋元本作翮，依汲古。第三句宋本、汲古作過我成邑，元本作過我城邑，依《小畜》之《革》校。</p><h3 id="巽之坎" tabindex="-1">巽之坎 <a class="header-anchor" href="#巽之坎" aria-label="Permalink to “巽之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>時鵠抱子，見蛇何咎。室傢俱在，不失其所。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《鼎》。</p><h3 id="巽之離" tabindex="-1">巽之離 <a class="header-anchor" href="#巽之離" aria-label="Permalink to “巽之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>隱隱大雷，霧霈為雨。有女痴狂，驚駭鄰裡。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏震為雷，重坎，故曰霧霈為雨。巽為女，巽進退，故曰痴狂。伏震為驚駭，艮為里。</p><h3 id="巽之咸" tabindex="-1">巽之咸 <a class="header-anchor" href="#巽之咸" aria-label="Permalink to “巽之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>無足斷跟，居處不安，凶惡為患。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《蹇》。</p><h3 id="巽之恒" tabindex="-1">巽之恒 <a class="header-anchor" href="#巽之恒" aria-label="Permalink to “巽之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>破筐敝筥，棄捐於道，不復為寶。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為筐筥、為道、為寶，兌毀，故破敝，故棄捐。</p><h3 id="巽之遯" tabindex="-1">巽之遯 <a class="header-anchor" href="#巽之遯" aria-label="Permalink to “巽之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>三雞啄粟，十雛從食。飢鳶卒擊，亡其兩叔。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳《中孚》之《頤》。</p><h3 id="巽之大壯" tabindex="-1">巽之大壯 <a class="header-anchor" href="#巽之大壯" aria-label="Permalink to “巽之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>乘車七百，以明文德。踐土葵丘，齊晉受福。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《兌》之《剝》。</p><h3 id="巽之晉" tabindex="-1">巽之晉 <a class="header-anchor" href="#巽之晉" aria-label="Permalink to “巽之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>百足俱行，相輔為強。三聖翼事，王室寵光。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《履》。</p><h3 id="巽之明夷" tabindex="-1">巽之明夷 <a class="header-anchor" href="#巽之明夷" aria-label="Permalink to “巽之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>典冊法書，藏閣蘭台。雖遭潰亂，獨不遇災。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《大畜》。閣，汲古作在，依宋元本。此以坤為書冊，火在下，故不遇。</p><h3 id="巽之家人" tabindex="-1">巽之家人 <a class="header-anchor" href="#巽之家人" aria-label="Permalink to “巽之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>西誅不服，恃強負力。倍道趨敵，師徒敗覆。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《屯》。西，宋元本作四，依汲古。趨，汲古作奔，依宋元本。</p><h3 id="巽之睽" tabindex="-1">巽之睽 <a class="header-anchor" href="#巽之睽" aria-label="Permalink to “巽之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>春陽生草，夏長條。萬物蕃滋，充寶益有。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《井》之《巽》。</p><h3 id="巽之蹇" tabindex="-1">巽之蹇 <a class="header-anchor" href="#巽之蹇" aria-label="Permalink to “巽之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>磝磽禿白，不生黍稷。無以供祭，祇靈乏祀。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦巽象。巽為白，寡髪，故曰禿白。艮山，故曰磝磽。磝磽，山田小石也。巽為黍稷，兌毀，故不生。震為祭、為神，故曰祇靈。震伏，故乏祀。○磝磽，宋元本作磝磝，依汲古。乏，汲古作代，依宋元本。</p><h3 id="巽之解" tabindex="-1">巽之解 <a class="header-anchor" href="#巽之解" aria-label="Permalink to “巽之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>牽衣涉河，水深漬罷。幸賴舟子，濟脫無他。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《萃》。第二句汲古作澗流浚多，依宋元本。罷，音婆。《唐韻正》雲：凡經傳中罷倦之罷皆音婆，今人音皮而誤。按：林以罷與河韻，正與韻正說合。</p><h3 id="巽之損" tabindex="-1">巽之損 <a class="header-anchor" href="#巽之損" aria-label="Permalink to “巽之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>宜行賈市，所求必倍。載喜抱子，與利為友。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《恆》。戴，汲古作載，依宋元本。</p><h3 id="巽之益" tabindex="-1">巽之益 <a class="header-anchor" href="#巽之益" aria-label="Permalink to “巽之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>兄徵東夷，弟伐遼西。大克勝還，封居河間。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為兄、為東、為徵，互坤，故曰東夷。伏兌為西，坤水，故曰遼西、曰河間。艮為封。○居，宋元本作君，依汲古。</p><h3 id="巽之夬" tabindex="-1">巽之夬 <a class="header-anchor" href="#巽之夬" aria-label="Permalink to “巽之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>初雖驚惶，後乃無傷。受其福慶，相孝為王。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為福慶、為王，相孝為王，言輔相秦孝公，使秦稱王也。似指商鞅。兌西，故曰商。</p><h3 id="巽之姤" tabindex="-1">巽之姤 <a class="header-anchor" href="#巽之姤" aria-label="Permalink to “巽之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>隨風乘龍，與利相逢。田獲三倍，商旅有功。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>憧憧之邑，長安無他。巽風乾龍，故曰隨風乘龍。巽為利、為三倍，伏震為田，故曰田獲三倍。巽為商旅，伏坤為邑、為安，巽為長，故曰長安。他蛇古通，巽為蛇，中孚初爻有他不燕，即以巽為蛇，林本易也。</p><h3 id="巽之萃" tabindex="-1">巽之萃 <a class="header-anchor" href="#巽之萃" aria-label="Permalink to “巽之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>魚擾水濁，寇圍吾邑。城危不安，驚恐狂惑。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤巽皆為魚，而坤為水，坤黃，故曰水濁。風散，故曰魚擾。坤為吾、為邑，巽為寇，故曰寇圍吾邑。艮為城，風隕，故曰城危。坤為憂懼，為迷，故曰驚恐狂惑。</p><h3 id="巽之升" tabindex="-1">巽之升 <a class="header-anchor" href="#巽之升" aria-label="Permalink to “巽之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>雖塞復通，履危不凶，保其明功。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為閉塞，震為通、為履，互大坎為危，故曰履危。坤為凶，震解，故不凶。○汲古多以道立宗四字，宋元本無。塞，宋元本作窮，依汲古。</p><h3 id="巽之困" tabindex="-1">巽之困 <a class="header-anchor" href="#巽之困" aria-label="Permalink to “巽之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>坤厚地德，庶物蕃息。平康正直，以綏大福。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>巽為庶物，伏震為蕃鮮，故曰蕃息。伏坎為平、為正直，震為大福。</p><h3 id="巽之井" tabindex="-1">巽之井 <a class="header-anchor" href="#巽之井" aria-label="Permalink to “巽之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>山水暴怒，壞梁折柱。稽難行旋，留連愁苦。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《咸》之《豫》。</p><h3 id="巽之革" tabindex="-1">巽之革 <a class="header-anchor" href="#巽之革" aria-label="Permalink to “巽之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>使燕築室，身不庇宿。家無聊賴，瀸我衣服。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>兌為燕，伏艮為室、為築、為身、為庇，艮伏，故曰身無庇宿，曰家無聊賴。坎為宿，艮為家也。伏震為衣，坤水，故曰瀸我衣服。瀸，濕也。○瀸，汲古作織，依宋元本。</p><h3 id="巽之鼎" tabindex="-1">巽之鼎 <a class="header-anchor" href="#巽之鼎" aria-label="Permalink to “巽之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>矢石所射，襄公劇。吳子巢門，傷病不治。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坎為矢、為射，艮為石，震為公、為輔佐，故曰襄公。，病也。按：宋襄公與楚戰，傷股而病，坤死，故曰劇。震為子、為言，故曰吳子。《說文》吳，大言也。《詩周頌》不吳不敖，《魯頌》不吳不場，《傳》吳，嘩也，故震為吳，坤為門，艮為巢，故曰巢門。襄二十五年，諸樊伐楚門於巢，巢牛臣射之，卒。坤死，故曰傷病不治。○，《公羊傳》大災者何，紵也。註：疾病也。元本訛痢，依宋本、汲古。門於巢，杜註雲：將攻巢門。</p><h3 id="巽之震" tabindex="-1">巽之震 <a class="header-anchor" href="#巽之震" aria-label="Permalink to “巽之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>日月運行，一寒一暑。榮寵赫赫，不可得保。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>顛顛墜墜，更為士伍。詳《中孚》之《晉》。</p><h3 id="巽之艮" tabindex="-1">巽之艮 <a class="header-anchor" href="#巽之艮" aria-label="Permalink to “巽之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>宮門悲鳴，臣圍其君，不得東西。艮為宮門，互坎為悲，震為鳴、為君。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為臣，上艮下艮，震君在中，故曰臣圍其君。震東，坎西，坎陷，艮止，故曰不得東西。</p><h3 id="巽之漸" tabindex="-1">巽之漸 <a class="header-anchor" href="#巽之漸" aria-label="Permalink to “巽之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>戴盆望天，不見星辰。顧小失大，福逃牆外。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《蒙》。</p><h3 id="巽之歸妹" tabindex="-1">巽之歸妹 <a class="header-anchor" href="#巽之歸妹" aria-label="Permalink to “巽之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>天之所明，禍不遇家。反目相逐，終得知美。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>小畜以離為反目，茲二至四互離，故亦曰反目。震為逐，坎為和。○目，宋元本作自，美作鳴，均依汲古。</p><h3 id="巽之豐" tabindex="-1">巽之豐 <a class="header-anchor" href="#巽之豐" aria-label="Permalink to “巽之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>天陰霖雨，塗行泥潦。商人休止，市無所有。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《夬》之《大過》。</p><h3 id="巽之旅" tabindex="-1">巽之旅 <a class="header-anchor" href="#巽之旅" aria-label="Permalink to “巽之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>嘉門福喜，增累盛熾。日就有德，宜其家國。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>艮為門，伏震為福喜、為盛熾。離為日，艮為家國。○第四句宋元本作宜民宜國，茲依汲古。</p><h3 id="巽之巽" tabindex="-1">巽之巽 <a class="header-anchor" href="#巽之巽" aria-label="Permalink to “巽之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>溫山松柏，常茂不落。鸞鳳以庇，得其歡樂。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《恆》。</p><h3 id="巽之兌" tabindex="-1">巽之兌 <a class="header-anchor" href="#巽之兌" aria-label="Permalink to “巽之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>南山之陽，華葉將將。嘉樂君子，為國寵光。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《大有》。此皆用旁通象。</p><h3 id="巽之渙" tabindex="-1">巽之渙 <a class="header-anchor" href="#巽之渙" aria-label="Permalink to “巽之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>畫龍頭頸，文章未成。甘言美語，詭辭無名。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《噬嗑》。詭，宋元本作說，茲依汲古。</p><h3 id="巽之節" tabindex="-1">巽之節 <a class="header-anchor" href="#巽之節" aria-label="Permalink to “巽之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>嬰兒孩子，未有知識。彼童而角，亂我政事。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《大畜》。以震為孩子可證《明夷》五爻非箕子也。</p><h3 id="巽之中孚" tabindex="-1">巽之中孚 <a class="header-anchor" href="#巽之中孚" aria-label="Permalink to “巽之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>陰作大姧，欲君勿言。鴻鵠利口，發其禍端。荊季懷憂，張伯被患。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>通《小過》。坎為姧，互大坎，故曰大姦。震為君、為言，艮止，故曰勿言。震為鴻鵠，兌為口，互巽，故曰利口。震為荊、為張伯，艮季，坎為憂患。○其，宋元本作患，依汲古。端，汲古作亂，依宋元本。</p><h3 id="巽之小過" tabindex="-1">巽之小過 <a class="header-anchor" href="#巽之小過" aria-label="Permalink to “巽之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>德之流行，利之四鄉。雨師灑道，風伯逐殃。巡狩封禪，以告成功。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《復》。</p><h3 id="巽之既濟" tabindex="-1">巽之既濟 <a class="header-anchor" href="#巽之既濟" aria-label="Permalink to “巽之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>禹將為君，裝入昆侖。稍進陽光，登見溫湯，功德昭明。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>坎為湯，下離，故曰溫湯。離為陽光、為照明，餘皆用半震半艮。</p><h3 id="巽之未濟" tabindex="-1">巽之未濟 <a class="header-anchor" href="#巽之未濟" aria-label="Permalink to “巽之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>五嶽四瀆，含潤為德。行不失理，民賴恩福。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《明夷》。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
